use std::fs::File;
use std::io::prelude::*;
use std::io::BufReader;
use std::path::Path;
use std::collections::HashMap;

use serde::{Deserialize, Serialize};

use serde_json::{Map, Value};

#[derive(Serialize, Deserialize)]
pub(crate) struct Config {
    pub host: String,
    pub enable_https: bool,
    pub tls_cert_path: String,
    pub tls_key_path: String,
    pub reject_response_status: u16,
    pub reject_response_body: String,
    pub proxy_mapping: Map<String, Value>
}

static CONFIG_FILE: &str = "log4jail.json";

impl Config {
    /// Default config file values
    pub fn default() -> Self {
        let mut default_proxy_mapping: Map<String, Value> = Map::default();

        default_proxy_mapping.insert("1337".into(), "http://127.0.0.1:8080/".into());
        default_proxy_mapping.insert("6969".into(), "http://127.0.0.1:9000/".into());

        Self {
            host: "127.0.0.1".into(),
            enable_https: false,
            tls_cert_path: "cert.pem".into(),
            tls_key_path: "key.rsa".into(),
            reject_response_status: 403,
            reject_response_body: "This request has been blocked.".into(),
            proxy_mapping: default_proxy_mapping
        }
    }

    /// Generate a boilerplate config file
    pub fn generate_default() {
        if !Path::new(CONFIG_FILE).exists() {
            let json_config = serde_json::to_string_pretty(&Self::default()).unwrap();
            let mut config_file = File::create(CONFIG_FILE).unwrap();

            config_file.write_all(json_config.as_bytes()).unwrap();

            eprintln!("[>] A default log4jail config has been generated, configure `log4jail.json` to start the proxy!\n");
            std::process::exit(0)
        }
    }

    /// Fetch config values from `log4jail.json`
    pub fn get_config() -> Self {
        let file = File::open(CONFIG_FILE).unwrap();

        let mut buf_reader = BufReader::new(file);
        let mut user_config = String::new();
        buf_reader.read_to_string(&mut user_config).unwrap();

        let config: Config = serde_json::from_str(&user_config).unwrap();
        config
    }


    /// Returns a standard HashMap of the proxy server mapping
    pub fn proxy_map() -> HashMap<u16, String> {
        let config = Self::get_config();

        let mut map: HashMap<u16, String> = HashMap::new();

        for (port, target) in config.proxy_mapping.iter() {
            map.insert(
                port.parse::<u16>().unwrap(),    
                target.as_str().unwrap().into(),
            );
        }

        map
    }
}

use warp::{
    hyper::body::Bytes,
    Filter,
    Rejection,
    http::{Response, HeaderMap}
};

use warp_reverse_proxy::{errors, extract_request_data_filter, proxy_to_and_forward_response};

use regex::Regex;
use once_cell::sync::Lazy;

use std::collections::HashMap;

static LOG4J_PAYLOAD_REGEXP: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"(?i)(\$|%24)(\{|%7b).*j.*n.*d.*i.*(:|%3a)").unwrap()
});

mod config;
use config::Config;

static CONFIG: Lazy<Config> = Lazy::new(|| {
    Config::get_config()
});

async fn reject_request() -> Result<http::Response<Bytes>, Rejection> {
    let response = Response::builder()
        .status(CONFIG.reject_response_status)
        .body(Bytes::from(CONFIG.reject_response_body.as_str()));

    response
        .map_err(errors::Error::HTTP)
        .map_err(warp::reject::custom)
}

#[tokio::main]
async fn main() {
    eprintln!("\n\t- ${{jndi:log4jail}} -\n");

    Config::generate_default();

    static PROXY_MAPPING: Lazy<HashMap<u16, std::string::String>> = Lazy::new(|| {
        Config::proxy_map()
    });

    // get host address octets
    let host_string: Vec<&str> = CONFIG.host.split(".").collect();

    let mut host: Vec<u8> = Vec::with_capacity(4);
    for octet in host_string {
        host.push(octet.parse::<u8>().unwrap())
    }

    let host = [host[0], host[1], host[2], host[3]];    

    for (port, target) in PROXY_MAPPING.iter() {        
        let request_filter = extract_request_data_filter();

        let app = warp::any()
            .and(request_filter)
            .and_then(move |path, query, method, headers: HeaderMap, body: Bytes| async move {
                for (k, v) in headers.iter() {
                    if LOG4J_PAYLOAD_REGEXP.is_match(k.as_str()) || LOG4J_PAYLOAD_REGEXP.is_match(v.to_str().unwrap()) {
                        return reject_request().await
                    }
                }

                if LOG4J_PAYLOAD_REGEXP.is_match(
                    std::str::from_utf8(&body).expect("error converting bytes to &str")
                ) {
                    return reject_request().await
                }     

                proxy_to_and_forward_response(
                    target.to_string(),
                    "".to_string(),
                    path,
                    query,
                    method,
                    headers,
                    body,
                ).await
            });

        tokio::spawn(async move {
            if CONFIG.enable_https {
                warp::serve(app)
                    .tls()
                    .cert_path(&CONFIG.tls_cert_path)
                    .key_path(&CONFIG.tls_key_path)
                    .run((host, *port)).await
            } else {
                warp::serve(app)
                    .run((host, *port)).await
            }
        });

        eprintln!("[-] Mapped port {} -> {}", port, target);
    }

    // keep running all proxy instances
    loop {}
}
